INSERT INTO academy_courses (slug, title, description, icon, color, order_index, difficulty, requires_pro, is_published) VALUES
  ('reading-a-stock-quote', 'Reading a Stock Quote', 'Decode everything on a stock quote — price, bid/ask, volume, market cap, and the day range — so the numbers stop being noise.', 'LineChart', 'emerald', 3, 'beginner', FALSE, TRUE)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO academy_lessons (course_id, slug, title, type, order_index, xp_reward, content)
SELECT
  (SELECT id FROM academy_courses WHERE slug = 'reading-a-stock-quote'),
  v.slug, v.title, v.type, v.order_index, v.xp_reward, v.content
FROM (VALUES
  ('anatomy-of-a-quote', 'Anatomy of a Quote', 'read', 0, 10, '{"sections":[{"text":"Every time you look up a stock, you''ll see a handful of numbers packed together. The most important one is the last price — that''s what a single share cost during the most recent trade. Think of it like a price tag that updates constantly throughout the trading day as people buy and sell.","highlightedTerms":[{"term":"last price","definition":"The price at which the most recent share of a stock was bought or sold. It updates continuously while the market is open."}]},{"text":"Right next to the price you''ll usually see the change and the % change. The change tells you how many dollars the price moved since yesterday, and the % change shows that same move as a percentage. A green number means the stock is up today; a red number means it''s down.","highlightedTerms":[{"term":"change","definition":"The dollar difference between the current price and yesterday''s closing price. Positive means up, negative means down."},{"term":"% change","definition":"The same price move shown as a percentage, which makes it easy to compare stocks of very different prices."}]},{"text":"To make sense of today''s move, you need a starting point — that''s the previous close, the final price from yesterday''s trading session. The change and % change are both measured against this number. So if a stock closed at $100 yesterday and sits at $102 now, the change is +$2 and the % change is +2%.","highlightedTerms":[{"term":"previous close","definition":"The last price a stock traded at when the market closed the day before. It''s the baseline for today''s gain or loss."}]},{"text":"Finally, the day range shows the lowest and highest prices the stock has hit so far today. It tells you how bumpy the ride has been: a wide range means the price bounced around a lot, while a narrow range means it stayed fairly steady. Together, these fields give you a quick snapshot of a stock''s mood right now.","highlightedTerms":[{"term":"day range","definition":"The lowest and highest prices a stock has traded at during the current day, showing how much it moved."}]}],"funFact":"The very first stock ticker, invented in 1867, printed prices on a thin strip of paper — that''s where the phrase ''ticker-tape parade'' comes from, since people threw the leftover strips out of windows to celebrate!"}'::jsonb),
  ('bid-ask-spread', 'Bid, Ask & Spread', 'read', 1, 10, '{"sections":[{"text":"When you look at a stock, you''ll actually see two prices, not one. The bid is the highest price a buyer is willing to pay right now, and the ask is the lowest price a seller is willing to accept. Think of it like a market stall: you offer $9 (your bid), the seller wants $10 (their ask), and a deal happens somewhere in between.","highlightedTerms":[{"term":"Bid","definition":"The highest price a buyer is currently willing to pay for a stock."},{"term":"Ask","definition":"The lowest price a seller is currently willing to accept for a stock."}]},{"text":"The gap between the bid and the ask is called the spread. It exists because buyers always want to pay a little less and sellers always want to get a little more, so there''s a small no-man''s-land in between. If the bid is $9.98 and the ask is $10.00, the spread is just 2 cents.","highlightedTerms":[{"term":"Spread","definition":"The difference between the bid price and the ask price. A smaller spread usually means lower trading costs."}]},{"text":"The size of the spread is a clue about liquidity, which means how easily you can buy or sell without moving the price. A tight (small) spread usually means lots of buyers and sellers are active, so trading is smooth and cheap. A wide (large) spread often means fewer people are trading, so you may pay more to get in and get less when you leave.","highlightedTerms":[{"term":"Liquidity","definition":"How easily an asset can be bought or sold quickly without a big change in its price."}]},{"text":"A helpful habit: heavily traded stocks with high trading volume tend to have very tight spreads, while small, obscure stocks can have surprisingly wide ones. Checking the spread before you buy helps you avoid quietly overpaying.","highlightedTerms":[{"term":"Avg Volume","definition":"Average number of shares traded per day. Higher volume means it''s easier to buy and sell without affecting the price."}]}],"funFact":"For the most active stocks like Apple, the spread can be as small as a single penny, but for thinly traded stocks it can balloon to several dollars per share."}'::jsonb),
  ('quote-quiz', 'Quick Check: Quote Fields', 'quiz', 2, 20, '{"questions":[{"question":"You see a stock quote showing a ''bid'' of $50.00 and an ''ask'' of $50.10. What does the ''ask'' price mean?","options":["The lowest price someone is willing to sell the stock for right now","The highest price someone is willing to pay for the stock right now","The price the stock closed at yesterday","The average price of the stock this year"],"correctIndex":0,"explanation":"The ask is the lowest price a seller will accept, so it''s what you''d pay to buy right now. The bid is the highest price a buyer will pay, so it''s what you''d get if you sold."},{"question":"A stock has a bid of $20.00 and an ask of $20.50. What is the ''spread''?","options":["$40.50","$20.25","$0.50","$20.50"],"correctIndex":2,"explanation":"The spread is simply the ask minus the bid ($20.50 - $20.00 = $0.50). A wider spread often means the stock trades less actively."},{"question":"A stock''s quote shows ''Change %: +3%'' and unusually high volume today. What does the high volume tell you?","options":["The stock is guaranteed to keep going up","A lot of shares are being traded today, meaning strong interest","The company earned 3% more money this year","The stock costs more than other stocks"],"correctIndex":1,"explanation":"Volume is the number of shares traded in a period, so high volume means lots of activity and interest — but it doesn''t predict which direction the price will go next."}]}'::jsonb),
  ('quote-vocab-match', 'Match the Quote Terms', 'match', 3, 15, '{"pairs":[{"term":"Bid","definition":"The highest price a buyer is willing to pay right now."},{"term":"Ask","definition":"The lowest price a seller is willing to accept right now."},{"term":"Spread","definition":"The gap between the bid and ask prices."},{"term":"Volume","definition":"How many shares traded during a set time period."},{"term":"Market Cap","definition":"A company''s total value: share price times all its shares."},{"term":"Day Range","definition":"The lowest and highest price a stock hit today."}]}'::jsonb),
  ('reading-volume', 'What Volume Tells You', 'read', 4, 10, '{"sections":[{"text":"Every time someone buys or sells a stock, that trade gets counted. Add up all those shares traded in a single day and you get the stock''s volume. Think of it like counting how many people walked through a store''s doors — it tells you how busy the stock was that day.","highlightedTerms":[{"term":"Avg Volume","definition":"Average number of shares traded per day. Higher volume means it''s easier to buy and sell without affecting the price."}]},{"text":"On its own, a single day''s volume doesn''t mean much. That''s why we compare it to the Avg Volume — the usual amount of trading over recent weeks. If a stock normally trades 1 million shares a day but suddenly trades 10 million, something unusual is grabbing people''s attention.","highlightedTerms":[{"term":"Avg Volume","definition":"Average number of shares traded per day. Higher volume means it''s easier to buy and sell without affecting the price."}]},{"text":"That sudden jump is called a volume spike, and it''s a signal that lots of people are reacting to something — maybe an earnings report, big news, or a rumor. A spike doesn''t tell you whether the news is good or bad, just that interest is high. Smart beginners treat it as a ''pay attention'' flag, then dig into why it happened.","highlightedTerms":[{"term":"volume spike","definition":"A day when trading volume jumps far above normal, signaling that something is drawing unusual attention to the stock."}]}],"funFact":"On some major news days, a single popular stock can trade more shares in a few hours than it normally does in an entire week."}'::jsonb),
  ('quote-scenario', 'Make the Call', 'scenario', 5, 25, '{"setup":"You open your app and see one of your stocks is down 3% today, colored bright red. Below the price, you notice the trading volume is huge — way more shares changed hands than usual — and there''s a note that the company just reported earnings last night. Your gut says ''sell before it drops more!'' What do you do first?","choices":[{"label":"Sell right away — a red number means it''s going down and I should get out.","feedback":"Totally understandable — that red number feels scary! But a single day''s price move doesn''t tell you WHY it moved. Selling on a gut reaction, before you understand what happened, often means locking in a loss just because of one bad-looking day. The color red just means ''lower than yesterday'' — it''s not a warning signal by itself.","isCorrect":false},{"label":"Read the earnings report and news to understand why the stock moved and whether anything real changed about the business.","feedback":"Exactly right! A price is just a headline — the story is underneath. Huge volume after earnings means lots of people are reacting to new information. Your job is to find out what that information is: Did sales grow? Did the company warn about the future? Understanding the ''why'' lets you make a calm, informed choice instead of reacting to a color.","isCorrect":true},{"label":"Buy more immediately — a 3% dip is a discount and stocks always bounce back.","feedback":"I love the calm energy, but this is reacting too — just in the other direction! ''It''s cheaper so buy more'' assumes the business is still healthy, and you don''t know that yet. Sometimes a stock drops on earnings because something genuinely got worse. Read the report first, THEN decide if it''s a real bargain or a warning sign.","isCorrect":false}]}'::jsonb)
) AS v(slug, title, type, order_index, xp_reward, content)
ON CONFLICT (course_id, slug) DO NOTHING;
